def welcome(c):
    n=c['slug'];topics=c['topics'];links=''.join(f'<a href="/search/label/{quote(t,safe="")}">{escape(t)}</a>' for t in topics)
    header=f'<div class="cl-welcome-copy"><p class="cl-kicker">{escape(c["audience"])}</p><h2>{escape(c["promise"])}</h2><p class="cl-intro">{escape(c["intro"])}</p></div>'
    nav=f'<nav aria-label="Browse topics" class="cl-topic-grid">{links}</nav>'
    note={'saffron':('In the kitchen','Something seasonal, something simple, something to share.'),'wayfarer':('A note for the road','The best itinerary leaves a little space between the plans.'),'lesson':('Choose a path','Read the explanation. Try the exercise. Keep what you learn.'),'bench':('Our approach','Describe the method. Show the evidence. Explain the trade-offs.')} .get(n,('A note from the editor',c['note']))
    aside=f'<aside class="cl-side-note"><strong>{escape(note[0])}</strong><p>{escape(note[1])}</p><a class="cl-text-link" href="#post-feed">Browse the journal ↗</a></aside>'
    index=f'<div class="cl-welcome-index"><p class="cl-kicker">Start here</p>{nav}</div>'
    structures={
      'recipe':header+aside+nav,'atlas':header+nav+aside,'learning':header+index+aside,
      'laboratory':header+aside+'<div class="cl-method-strip"><span>01 / Observe</span><span>02 / Compare</span><span>03 / Explain</span></div>'+nav,
      'workshop':header+aside+nav,'lookbook':header+nav+'<p class="cl-editor-note">A considered edit, made for real life.</p>',
      'journal':header+aside+nav,'care':header+nav+aside,'library':header+'<p class="cl-editor-note">A journal of reading, writing and paying attention.</p>'+nav,
      'arena':header+nav+'<div class="cl-method-strip"><span>PLAY / DISCOVER</span><span>READ / REFLECT</span></div>',
      'episodes':header+aside+nav,'botanical':aside+header+nav,'training':header+nav+aside,
      'ledger':header+aside+nav,'cinema':header+'<p class="cl-editor-note">Reviews. Recaps. The stories behind the screen.</p>'+nav,
      'bulletin':'<p class="cl-edition">The community edition · Stories from around here</p>'+header+nav,
      'casebook':header+nav+'<p class="cl-editor-note">Selected projects &amp; the thinking behind them.</p>',
      'product':header+aside+nav,'celebration':header+'<p class="cl-editor-note">Real stories, thoughtful details, good company.</p>'+nav,
      'campaign':header+aside+nav,
    }
    return f'<section class="cl-welcome cl-welcome-{c["layout"]}" aria-label="Introduction">{structures[c["layout"]]}</section>'

